cases = [
    {"q": "orders in march", "expected": [120]},
    {"q": "returns in march", "expected": [7]},
    {"q": "top sku", "expected": ["A1"]},
    {"q": "refunds total", "expected": [300]},
]
fake_results = {"orders in march": [120], "returns in march": [9],
                "top sku": ["A1"], "refunds total": None}

passed, failures = 0, []
for c in cases:
    got = fake_results[c["q"]]
    if got is None:
        failures.append((c["q"], "error"))
    elif got == c["expected"]:
        passed += 1
    else:
        failures.append((c["q"], "wrong"))
print(f"accuracy {passed}/{len(cases)} = {passed / len(cases):.0%}")
for q, why in failures:
    print("FAIL", q, why)
